INSERT OR IGNORE INTO ops_config (key, value, note) VALUES ('OWNER_DIRECTIVE_2026_10_19_DECISION_AUTOPROCEED_1', '{"id":"DECISION-AUTOPROCEED-1","directive":"REVERSIBLE FLEET DECISIONS SHALL ALWAYS TAKE THE RECOMMENDED OPTION AND PROCEED WITHOUT WAITING FOR APPROVAL","directive_verbatim":"reversible fleet decisions SHALL ALWAYS take the recommended option and proceed without waiting for approval","meaning":"A decision that has a recommended option and can be undone is taken in the same cycle: the loop or session acts on the recommendation, records it in decision_log with its revert path, and reports it as done. It does not present the options, wait for a reply or file an approval card. ''Reversible'' is the owner''s word and the test: undoable in one cycle, with no unbacked-up loss and no external authority. A decision that fails the test is not covered by this directive and keeps the existing rules.","scope":"No limit moves. The interrupt gate (irreversible and identity-bound), the section 9 limits (security, privacy, alignment floor), the harness''s own permission checks, the shared-secrets lock and another session''s live work claim keep their precedence over it, as over every autonomy rule. It adds no authority to act as the owner in a legal, financial or signing act.","machinery":["AUTONOMY-FIRST-1 (CLAUDE.md; charter decision rule 11; ops_config autonomy_first_gate)","IC-YES-001 and IC-ADOPT-001 (docs/DOCTRINE-KERNEL.md)","OWNER_DIRECTIVE_2026_10_17_ALWAYS_DEPLOY","AUTONOMY-DECISION-POLICY-1 tier T1 (docs/AUTONOMY-DECISION-POLICY.md)"],"honored_by":"the doctrine, the decision policy and the prompts that cite them; no worker reads this key, as none reads the 2026-10-17 directive''s key","docs":"written on branch claude/sleepy-feynman-ur06bb (docs/AUTONOMOUS-OPERATION-DOCTRINE.md standing directive 2026-10-19, docs/AUTONOMY-DECISION-POLICY.md, CLAUDE.md); lands with the next merge","source":"owner_prompts op-mvf44u22d8ed; agent_issues 100131","adopted_at":"2026-10-19"}', 'DECISION-AUTOPROCEED-1 (owner standing directive 2026-10-19, owner task op-mvf44u22d8ed, issue 100131): the fleet directive store, same shape as OWNER_DIRECTIVE_2026_10_17_ALWAYS_DEPLOY. Revert: DELETE this key.');
